from pathlib import Path
import json,html,hashlib,shutil
R=Path(__file__).resolve().parents[1];N='agent-sdk-github-repository-tour';P=R/'presentations'/N;V=R/'videos'/N
r=json.loads((V/'validation.json').read_text(encoding='utf-8'));assert r['fullVideoAndAudioDecode']=='passed';assert hashlib.sha256((V/r['file']).read_bytes()).hexdigest()==r['sha256']
t=json.loads((V/'timeline.json').read_text(encoding='utf-8'));story=json.loads((P/'storyboard.json').read_text(encoding='utf-8'))
shutil.copy2(P/'.build/video/slides/slide-01.png',V/'cover.png')
provenance=json.loads((P/'screenshot-provenance.json').read_text(encoding='utf-8'))
for capture in provenance:capture['screenshotSha256']=hashlib.sha256((P/f'.build/video/slides/slide-{capture["slide"]:02}.png').read_bytes()).hexdigest()
(V/'screenshot-provenance.json').write_text(json.dumps(provenance,indent=2),encoding='utf-8')
chapters=[]
for row,s in zip(t['slides'],story):
 sec=int(row['start']);chapters.append(f'<li><button data-start="{row["start"]}" onclick="const v=document.querySelector(\'video\');v.currentTime=Number(this.dataset.start);v.play()">{sec//60}:{sec%60:02} · {html.escape(s["title"])}</button></li>')
page=(V/'index.html').read_text(encoding='utf-8').replace('poster="highlight-preview.jpg"','poster="cover.png"')
extra='<section><h2>Lesson chapters</h2><ol style="columns:2;line-height:2">'+''.join(chapters)+'</ol><p>The browser scenes are real GitHub screenshots of the updated README and source folders. Setup commands are explained from the documentation; this recording does not claim a new installation or live provider execution.</p><p><a href="https://github.com/luiscoco/Udemy-Claude-Agent-SDK-Student-Rebuild">Repository</a> · <a href="github-review.json">Reviewed snapshot</a> · <a href="screenshot-provenance.json">Screenshot provenance</a> · <a href="narration-script.txt">Narration script</a> · <a href="geometry-audit.json">Highlight geometry</a></p></section><style>button{background:none;border:0;color:#f2b48f;font:inherit;text-align:left;cursor:pointer}li{break-inside:avoid}@media(max-width:750px){ol{columns:1!important}}</style>'
if 'Lesson chapters' not in page:page=page.replace('</main>',extra+'</main>')
(V/'index.html').write_text(page,encoding='utf-8')
sec=int(r['durationSeconds']);stamp=f'{sec//60}:{sec%60:02}'
catalog=R/'videos/index.html';body=catalog.read_text(encoding='utf-8');card=f'<article data-project="{N}"><span>CLAUDE AGENT SDK · GITHUB REPOSITORY TOUR</span><a href="{N}/index.html"><img loading="lazy" src="{N}/cover.png" alt="Explore the GitHub Repository"></a><div><h2>Learning Platform: GitHub Repository Tour</h2><p>Verified · {stamp} · 1080p · Real GitHub screenshots · Updated student README</p><a href="{N}/{r["file"]}">MP4</a> · <a href="{N}/index.html">Player and chapters</a></div></article>'
if f'data-project="{N}"' not in body:catalog.write_text(body.replace('<main>','<main>'+card,1),encoding='utf-8')
(V/'README.txt').write_text(f'CLAUDE AGENT SDK LEARNING PLATFORM: GITHUB REPOSITORY TOUR\nDuration: {stamp}. 1920x1080, 30 fps, H.264/AAC. Inworld Yash, TTS 2, balanced delivery, enhanced generation, speaking rate 1.25, 48kHz.\n\n17 scenes: branded cover; real GitHub repository; README navigation; setup; ports and startup; first prepared lesson; optional live exercise; learning features; local persistence; student build materials; folder map; source and server directories; technology baseline; verification; troubleshooting; scope and next steps.\n\nREADME improved and published at commit 56fc40f. All 25 README links checked against the Git tree and all documented npm run commands checked against package scripts. Original detailed README preserved as DEVELOPMENT_HISTORY.md. No application runtime was changed; no full regression or new live model run is claimed.\n\nBrowser screenshots use the actual GitHub website. Native DOM text coordinates and provider word timestamps drive highlights. See screenshot-provenance.json, geometry-audit.json, validation.json and phrase-boundary report.\n\nRebuild: python scripts/create-sdk-github-tour.py; node scripts/capture-sdk-github-tour.mjs; python scripts/create-sdk-github-tour.py; python scripts/audit-sdk-github-tour.py; python -u scripts/build-narrated-presentation.py --project {N}; python scripts/finish-sdk-github-tour.py\n',encoding='utf-8')
print(f'Published local player with {len(chapters)} chapters; duration {stamp}.')
